class Solution {
public:
    int numMagicSquaresInside(vector<vector<int>>& grid) {
        int R = grid.size(), C = grid[0].size();
        if (R < 3 || C < 3) return 0;

        auto isMagic = [&](int r, int c) -> bool {
            if (grid[r + 1][c + 1] != 5) return false;
            vector<int> count(16, 0);
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 3; ++j) {
                    int val = grid[r + i][c + j];
                    if (val < 1 || val > 9 || count[val] > 0) return false;
                    count[val]++;
                }
            }
            for (int i = 0; i < 3; ++i) {
                if (grid[r + i][c] + grid[r + i][c + 1] + grid[r + i][c + 2] != 15) return false;
            }
            for (int j = 0; j < 3; ++j) {
                if (grid[r][c + j] + grid[r + 1][c + j] + grid[r + 2][c + j] != 15) return false;
            }
            if (grid[r][c] + grid[r + 1][c + 1] + grid[r + 2][c + 2] != 15) return false;
            if (grid[r][c + 2] + grid[r + 1][c + 1] + grid[r + 2][c] != 15) return false;
            return true;
        };

        int count = 0;
        for (int r = 0; r + 2 < R; ++r) {
            for (int c = 0; c + 2 < C; ++c) {
                if (isMagic(r, c)) count++;
            }
        }
        return count;
    }
};

class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        int R = grid.length, C = grid[0].length;
        if (R < 3 || C < 3) return 0;

        int count = 0;
        for (int r = 0; r + 2 < R; ++r) {
            for (int c = 0; c + 2 < C; ++c) {
                if (isMagic(grid, r, c)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagic(int[][] grid, int r, int c) {
        if (grid[r + 1][c + 1] != 5) return false;
        int[] freq = new int[16];
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                int val = grid[r + i][c + j];
                if (val < 1 || val > 9 || freq[val] > 0) return false;
                freq[val]++;
            }
        }
        for (int i = 0; i < 3; ++i) {
            if (grid[r + i][c] + grid[r + i][c + 1] + grid[r + i][c + 2] != 15) return false;
        }
        for (int j = 0; j < 3; ++j) {
            if (grid[r][c + j] + grid[r + 1][c + j] + grid[r + 2][c + j] != 15) return false;
        }
        if (grid[r][c] + grid[r + 1][c + 1] + grid[r + 2][c + 2] != 15) return false;
        if (grid[r][c + 2] + grid[r + 1][c + 1] + grid[r + 2][c] != 15) return false;
        return true;
    }
}

