var numMagicSquaresInside = function(grid) {
    const R = grid.length;
    const C = grid[0].length;
    if (R < 3 || C < 3) return 0;

    function isMagic(r, c) {
        if (grid[r + 1][c + 1] !== 5) return false;
        const seen = new Array(10).fill(false);
        for (let i = 0; i < 3; i++) {
            for (let j = 0; j < 3; j++) {
                const val = grid[r + i][c + j];
                if (val < 1 || val > 9 || seen[val]) return false;
                seen[val] = true;
            }
        }
        for (let i = 0; i < 3; i++) {
            if (grid[r + i][c] + grid[r + i][c + 1] + grid[r + i][c + 2] !== 15) return false;
        }
        for (let j = 0; j < 3; j++) {
            if (grid[r][c + j] + grid[r + 1][c + j] + grid[r + 2][c + j] !== 15) return false;
        }
        if (grid[r][c] + grid[r + 1][c + 1] + grid[r + 2][c + 2] !== 15) return false;
        if (grid[r][c + 2] + grid[r + 1][c + 1] + grid[r + 2][c] !== 15) return false;
        return true;
    }

    let count = 0;
    for (let r = 0; r + 2 < R; r++) {
        for (let c = 0; c + 2 < C; c++) {
            if (isMagic(r, c)) count++;
        }
    }
    return count;
};
